"  const fetchBarData = async () => {
    if (!isAuthenticated) return;
    const start = barStartDate || new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    const end = barEndDate || new Date().toISOString().split('T')[0];

    let rangeOrders = [];
    if (navigator.onLine) {
      try {
        const res = await posService.getAllOrders({
          startDate: start + ' 00:00:00',
          endDate: end + ' 23:59:59'
        });
        rangeOrders = res.data || [];
      } catch (err) {
        console.warn("Failed to fetch bar chart data from server, falling back to local orders:", err);
        rangeOrders = recentOrders || [];
      }
    } else {
      rangeOrders = recentOrders || [];
    }

    if (!rangeOrders || rangeOrders.length === 0) return;"
